sys_variable_value.value:
(function execute(inputs, outputs) {

  var SUPPLIER_BANKING_INFO_TASK = "e143c55f9373cb50e2987af08bba1031";   // Provide GST details;
  var TASK_TYPE = "submit_catalog";
  var TASK_AUDIENCE = "external";
  var STATE = 1; // For "Awaiting completion" state
  var isTaskCreationFromCI = false;


  var supplierTaskObj = {
    assigned_to: inputs.assigned_to_sysid,
    parent: inputs.parent_supplier_case_sysid,
    short_description: "Provide GST details for " + inputs.supplier_name,
    action_type_for_task: TASK_TYPE,
    task_audience: TASK_AUDIENCE,
    catalog_item: SUPPLIER_BANKING_INFO_TASK,
    state: STATE
  };

  var supplierCommonUtil = new sn_slm.SupplierCommonUtil();
  var supplierTaskSysId = supplierCommonUtil.createSupplierTask(supplierTaskObj, isTaskCreationFromCI);

  outputs.task_sys_id = supplierTaskSysId;

})(inputs, outputs);

